+bool PhiNode::cmp(const Node& n) const {
+  const PhiNode& other = static_cast<const PhiNode&>(n);
+  if (!TypeNode::cmp(other) || _adr_type != other._adr_type) {
+    return false;
+  }
+  return _adr_type != TypePtr::BOTTOM || _excluded_idx == other._excluded_idx;
